            $(""#gubun2"").val('L'");
            WriteLiteral(@");

        } else if ((preFix == ""W"") || (preFix == ""Z"") || (preFix == ""C"")) {     // 장소 바코드라면.
            $(""#div_area1"").show(""fast"");
            //$(""#div_area2"").show(""fast"");
            $(""#area_cd"").val(params.barcode);
            fn_init('pallet');
            $(""#gubun2"").val('A');
        }
    }

